class C:
 def startswith(self,prefix): return prefix
print(C().startswith(7),C().startswith(prefix=8))

def run(text,args): return text.startswith(*args)
for args in [(),('a',),('b',1),('b',1,2),('a',0,3,4)]:
 try: print(run('abc',args))
 except TypeError: print('rejected')

def run(prefix): return 'abc'.startswith((prefix,None))
print(run('a'))
try: run('x')
except TypeError: print('rejected')

for options in [{'start':0},{'end':3}]:
 try: print('abc'.startswith('a',**options))
 except TypeError: print('rejected')

print('abc'.startswith(('a',None)))
def match(value):return 'abc'.startswith(value)
try:match((None,'a'))
except TypeError:print('rejected')

try:'abc'.startswith(prefix='a')
except TypeError:print('rejected')
else:print('accepted')
try:'abc'.endswith(suffix='c')
except TypeError:print('rejected')
else:print('accepted')

for value in [None,1,[],b'a']:
 try:'abc'.startswith(value)
 except TypeError:print('rejected')

print('abc'.endswith(('c',None)))
def match(value):return 'abc'.endswith(value)
try:match((None,'c'))
except TypeError:print('rejected')

for name in ['startswith','endswith']:
 method=getattr('abc',name)
 try:method(**{'prefix' if name=='startswith' else 'suffix':'a'})
 except TypeError:print('rejected')
 else:print('accepted')

def run(text): return text.startswith(('x',None))
print(run('xyz'))
try:run('abc')
except TypeError:print('rejected')
